    query_result="$(
      "${compose[@]}" exec -T prometheus \
        wget -qO- \
        'http://127.0.0.1:9090/api/v1/query?query=count(http_requests_total)' \
        2>/dev/null || true
    )"

    up_count="$(
      printf '%s\n' "$targets" | \
        jq -r '[.data.activeTargets[] | select(.health == "up")] | length' \
